pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {demo} from "../src/demo.sol";

contract InvMutTest is Test {
    demo c;
    function setUp() public { c = new demo(); }

    // fuzz parameter: an address (from) and an address for caddress are fuzzed
    // we only need to fuzz one parameter per harness rules; include an address to pass as `from`
    function testFuzz_property(address from) public {
        // We will call transfer with an EMPTY _tos array and any uint value (use 0).
        address[] memory tos = new address[](0);
        bool ok;
        // call through try/catch to observe whether it reverts (reference should revert for empty array)
        try c.transfer(from, address(0x1234), tos, uint256(0)) {
            ok = true;
        } catch {
            ok = false;
        }
        // The universal property: for any inputs, the reference C reverts on empty _tos,
        // so ok must be false. The mutant removes the require and will return true for some inputs,
        // making ok true — thus the assertion distinguishes them.
        assertTrue(!ok);
    }
}

